import * as Sentry from "@sentry/nextjs/cloudflare";
import { scrubBreadcrumb, scrubEvent } from "@hilltop/shared/telemetry";
import { accessAllows } from "./access";
/* eslint-disable @typescript-eslint/ban-ts-comment */
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import handler from "./.open-next/worker.js";

/*
 * The deployed Worker: OpenNext's handler wrapped by Sentry, so server errors and
 * request traces are reported. Next.js catches errors while rendering and logs them
 * instead of throwing, so logged errors are reported too, without personal data
 * (see @hilltop/shared/telemetry). (Next's instrumentation hook isn't used: its
 * server chunk isn't bundled for Workers.) `next dev` doesn't use this file.
 *
 * Every request must also have passed Cloudflare Access when it's configured (see
 * access.ts), so the portal isn't reachable around it.
 */

type Env = {
  SENTRY_DSN?: string;
  CF_VERSION_METADATA?: { id: string };
  CF_ACCESS_TEAM_DOMAIN?: string;
  CF_ACCESS_AUD?: string;
};

export default Sentry.withSentry(
  (env: Env) => ({
    dsn: env.SENTRY_DSN,
    release: env.CF_VERSION_METADATA?.id,
    environment: "production",
    tracesSampleRate: 0.1,
    beforeSend: scrubEvent,
    beforeBreadcrumb: scrubBreadcrumb,
    integrations: [Sentry.captureConsoleIntegration({ levels: ["error"] })],
  }),
  {
    async fetch(request: Request, env: Env, ctx: unknown) {
      if (env.CF_ACCESS_TEAM_DOMAIN && env.CF_ACCESS_AUD && !(await accessAllows(request, env.CF_ACCESS_TEAM_DOMAIN, env.CF_ACCESS_AUD))) {
        return new Response("Forbidden", { status: 403, headers: { "cache-control": "no-store" } });
      }
      return handler.fetch(request, env, ctx);
    },
  } as Parameters<typeof Sentry.withSentry<Env>>[1],
);
